"""Readable per-log source appendix; exactly the previously extracted unsmoothed measurements."""
from pathlib import Path
import sys,json,csv,collections
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
from report_data_v2 import read,save,sha
root=Path(sys.argv[1]);P=Path(sys.argv[2]);O=P/'figures';inventory=read(root/'inputs/s10/SOURCE_LOG_INVENTORY.json');manifest=read(P/'FIGURE_MANIFEST.json');source_map=read(P/'FIGURE_SOURCE_MAP.json');plt.rcParams.update({'font.size':11,'svg.hashsalt':'s11-source-appendix-v1','axes.spines.top':False,'axes.spines.right':False,'savefig.facecolor':'white'})
for source in inventory['sources']:
 rs=list(csv.DictReader((root/'inputs/s10/scalars'/source['relevant_scalar_table']).open()));train=[r for r in rs if r['tag']=='forget loss'];valid=[r for r in rs if r['tag']=='forget loss validation'];name='FORGET_SOURCE_'+source['label'].upper();fig,(ax,detail)=plt.subplots(1,2,figsize=(8,3.8),gridspec_kw={'width_ratios':[2,1]},layout='constrained');ax.plot([int(r['step']) for r in train],[float(r['value']) for r in train],color='#0072B2',lw=.7,label='forget loss');ax.scatter([int(r['step']) for r in valid],[float(r['value']) for r in valid],color='#D55E00',marker='x',s=35,label='forget loss validation');ax.set_ylim(1.38,1.68);ax.set_xlabel('Logged step');ax.set_ylabel('Original logged scalar');ax.grid(alpha=.15);ax.legend(fontsize=7,frameon=False);detail.scatter([int(r['step']) for r in valid],[float(r['value']) for r in valid],marker='x',s=35,color='#D55E00');detail.set_xlabel('Logged step');detail.set_ylabel('Validation detail');detail.ticklabel_format(style='plain',axis='y',useOffset=False);detail.grid(alpha=.15);fig.suptitle(source['label'].replace('_',' ')+' — source-log evidence; scientifically unqualified',fontsize=11,fontweight='bold');fig.supxlabel('Unsmoothed; all calls retained. Shared training scale; validation detail uses its own scale. No checkpoint-content match.',fontsize=7)
 exports=[]
 for ext in ['png','pdf','svg']:
  path=O/(name+'.'+ext);meta={'Date':None} if ext=='svg' else {'CreationDate':None,'ModDate':None} if ext=='pdf' else {'Software':'S11 source-only appendix'};fig.savefig(path,dpi=180,metadata=meta);exports.append({'path':'figures/'+path.name,'sha256':sha(path),'bytes':path.stat().st_size})
 plt.close(fig);manifest['figures'].append({'id':name,'family':'forget_source_detail','caption':'Original source '+source['id']+'; no smoothing or duplicate selection. Both training and validation labels are source labels, not independently qualified scientific metrics. Validation detail has a separate disclosed scale.','exports':exports,'source_records':len(train)+len(valid),'record_mapping_path':'FIGURE_SOURCE_MAP.json'})
 for r in train+valid:source_map.append({'figure':name,'source_type':'unqualified_forget_scalar','source_id':r['observation_id'],'source_file_id':r['source_id'],'tag':r['tag'],'step':int(r['step']),'x':int(r['step']),'y':float(r['value']),'ci_low':None,'ci_high':None,'checkpoint_content_binding':None,'scientific_qualification':'UNQUALIFIED','no_layerwise_projection':True})
save(P/'FIGURE_MANIFEST.json',manifest);save(P/'FIGURE_SOURCE_MAP.json',source_map);print('READABLE_SOURCE_APPENDIX_PAGES',len(inventory['sources']),flush=True)
